func TestQaA698UnrelatedWriteInterruptsConditionalCleanup(t *testing.T) {
 for _, kind := range []string{"project", "environment"} {
  t.Run(kind, func(t *testing.T) {
   svc, cl := newService(placementResource())
   tracking := &placementPatchClient{Client: cl}
   tracking.beforePatch = func() {
    updated := readPlacement(t, cl)
    if updated.Annotations == nil { updated.Annotations = map[string]string{} }
    updated.Annotations["qa-a698-unrelated"] = "preserve"
    if err := cl.Update(context.Background(), updated); err != nil { t.Fatal(err) }
   }
   svc.Client = tracking
   clear, expected := svc.ClearProjectID, "prj-a"
   if kind == "environment" { clear, expected = svc.ClearEnvironmentID, "env-a" }
   err := clear(ctxAs("user-a"), "placement", expected)
   if !apierrors.IsConflict(err) || tracking.patches != 1 { t.Fatalf("expected observed one-attempt conflict: err=%v attempts=%d", err, tracking.patches) }
   after := readPlacement(t, cl)
   if after.Labels[core.LabelProject] != "prj-a" || after.Labels[core.LabelEnvironment] != "env-a" { t.Fatal("failed attempt changed placement") }
   if err := clear(ctxAs("user-a"), "placement", expected); err != nil { t.Fatal(err) }
   final := readPlacement(t, cl)
   if final.Labels[core.LabelEnvironment] != "" || (kind == "project" && final.Labels[core.LabelProject] != "") || final.Annotations["qa-a698-unrelated"] != "preserve" || !slices.Equal(final.Spec.IPAllowList, after.Spec.IPAllowList) { t.Fatal("retry lost unrelated state or did not clear expected placement") }
   t.Logf("first call: raw Kubernetes conflict, 1 patch; explicit second call succeeds, unrelated annotation and owned rules retained; total patches=%d", tracking.patches)
  })
 }
}
